AlarmBands.kernel_code:
pub struct AlarmBands {
    /// `ceil16(max_safe_temp + alarm_hysteresis)`
    pub hi_on: i32,
    /// `ceil16(max_safe_temp - alarm_hysteresis)`
    pub hi_off: i32,
    /// `floor16(min_safe_temp - alarm_hysteresis)`
    pub lo_on: i32,
    /// `floor16(min_safe_temp + alarm_hysteresis)`
    pub lo_off: i32,
}

fan_valid.kernel_code:
pub fn fan_valid(f: FanBands) -> bool {
    SENSOR_MIN <= f.off_at && f.off_at < f.on_at && f.on_at <= SENSOR_MAX
}

FanBands.kernel_code:
pub struct FanBands {
    /// `ceil16(fan_on_threshold)`
    pub on_at: i32,
    /// `floor16(fan_off_threshold)`
    pub off_at: i32,
}

alarm_valid.kernel_code:
pub fn alarm_valid(b: AlarmBands) -> bool {
    // (`lo_off < hi_off` first, so `lo_off + 1` cannot overflow; an earlier
    // `hi_off - 1` underflowed at i32::MIN, which the proof caught)
    SENSOR_MIN <= b.lo_on
        && b.lo_on <= b.lo_off
        && b.lo_off < b.hi_off
        && b.lo_off + 1 < b.hi_off
        && b.hi_off <= b.hi_on
        && b.hi_on <= SENSOR_MAX
}

alarm_next.kernel_code:
pub fn alarm_next(on: bool, t: i32, b: AlarmBands) -> bool {
    if on {
        t >= b.hi_off || t <= b.lo_off
    } else {
        t >= b.hi_on || t <= b.lo_on
    }
}

fan_next.kernel_code:
pub fn fan_next(on: bool, t: i32, f: FanBands) -> bool {
    if t >= f.on_at {
        true
    } else if t <= f.off_at {
        false
    } else {
        on
    }
}
